 import React, { useState, useEffect } from 'react'
import { useAuth } from '../contexts/AuthContext'
import { footballApi, generateAIPrediction, getTeamEmoji } from '../services/footballApi'

export default function Home() {
    const { profile } = useAuth()
    const [matches, setMatches] = useState([])
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        async function loadMatches() {
            try {
                const events = await footballApi.getTodaysMatches()
                setMatches(events.slice(0, 5)) // Show top 5 matches
            } catch (error) {
                console.error('Error loading matches:', error)
            } finally {
                setLoading(false)
            }
        }
        loadMatches()
    }, [])

    return (
        <div>
            {/* Welcome Banner */}
            <div className="bg-gradient-to-r from-green-600 to-green-800 text-white rounded-2xl p-6 md:p-8 mb-8">
                <h1 className="text-2xl md:text-3xl font-bold">⚽ Welcome, {profile?.full_name || 'Predictor'}!</h1>
                <p className="text-green-100 mt-2">Predict matches, earn points, and climb the leaderboard</p>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6 mb-8">
                <div className="bg-white rounded-xl shadow-md p-6 text-center">
                    <div className="text-4xl mb-2">🏆</div>
                    <h3 className="font-bold text-gray-700">Your Points</h3>
                    <p className="text-2xl font-bold text-green-600">{profile?.points || 0}</p>
                </div>
                <div className="bg-white rounded-xl shadow-md p-6 text-center">
                    <div className="text-4xl mb-2">📊</div>
                    <h3 className="font-bold text-gray-700">Predictions</h3>
                    <p className="text-2xl font-bold text-green-600">{profile?.predictions_count || 0}</p>
                </div>
                <div className="bg-white rounded-xl shadow-md p-6 text-center">
                    <div className="text-4xl mb-2">🎯</div>
                    <h3 className="font-bold text-gray-700">Accuracy</h3>
                    <p className="text-2xl font-bold text-green-600">{profile?.accuracy || 0}%</p>
                </div>
            </div>

            {/* Today's Matches */}
            <div className="bg-white rounded-xl shadow-md p-6">
                <h2 className="text-xl font-bold text-gray-700 mb-4">📅 Today's Matches</h2>
                
                {loading ? (
                    <div className="text-center py-8 text-gray-500">Loading matches...</div>
                ) : matches.length === 0 ? (
                    <div className="text-center py-8 text-gray-400">
                        <p>No matches scheduled for today</p>
                        <p className="text-sm mt-2">Check back later for upcoming games</p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        {matches.map((match, index) => {
                            const ai = generateAIPrediction(match)
                            const homeName = match.strHomeTeam || 'Home'
                            const awayName = match.strAwayTeam || 'Away'
                            const homeEmoji = getTeamEmoji(homeName)
                            const awayEmoji = getTeamEmoji(awayName)
                            
                            // Determine predicted result
                            let resultText = 'Draw'
                            if (ai.result.home > ai.result.draw && ai.result.home > ai.result.away) resultText = 'Home Win'
                            else if (ai.result.away > ai.result.home && ai.result.away > ai.result.draw) resultText = 'Away Win'
                            
                            return (
                                <div key={index} className="border border-gray-200 rounded-xl p-4 hover:shadow-md transition">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center space-x-3">
                                            <span className="text-2xl">{homeEmoji}</span>
                                            <span className="font-semibold">{homeName}</span>
                                        </div>
                                        <span className="text-gray-400 font-bold">vs</span>
                                        <div className="flex items-center space-x-3">
                                            <span className="font-semibold">{awayName}</span>
                                            <span className="text-2xl">{awayEmoji}</span>
                                        </div>
                                    </div>
                                    <div className="mt-2 flex items-center justify-between text-sm">
                                        <span className="text-gray-500">🏆 {match.strLeague || 'Unknown League'}</span>
                                        <span className="text-gray-500">{match.dateEvent || 'Today'}</span>
                                    </div>
                                    <div className="mt-2 flex items-center justify-between bg-gray-50 rounded-lg p-2">
                                        <span className="text-xs text-gray-500">🤖 AI Prediction</span>
                                        <span className="font-semibold text-green-600">{resultText}</span>
                                        <span className="text-xs text-gray-400">{ai.confidence}% confidence</span>
                                    </div>
                                </div>
                            )
                        })}
                    </div>
                )}
            </div>
        </div>
    )
}
